package com.dmos.table;
import android.app.*;import android.os.*;import android.content.*;import android.content.res.Configuration;import android.graphics.Color;import android.graphics.Insets;import android.net.Uri;import android.print.PrintManager;import android.view.*;import android.webkit.*;import android.widget.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class MainActivity extends Activity {
 private static final String BASE="https://appassets.androidplatform.net/assets/";private WebView web;private WebView printWeb;private ValueCallback<Uri[]> chooser;private byte[] pendingExport;private String pendingName;private static final int IMPORT=41,EXPORT=42;
 private boolean local(Uri u){return "https".equals(u.getScheme())&&"appassets.androidplatform.net".equals(u.getHost())&&u.getPath()!=null&&u.getPath().startsWith("/assets/");}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(16,21,18));if(Build.VERSION.SDK_INT>=30){getWindow().setDecorFitsSystemWindows(false);root.setOnApplyWindowInsetsListener((v,insets)->{Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);return insets;});}else root.setFitsSystemWindows(true);
 LinearLayout toolbar=new LinearLayout(this);toolbar.setGravity(Gravity.CENTER_VERTICAL);TextView title=new TextView(this);title.setText("DMOS Table · Offline");title.setTextColor(Color.rgb(189,220,131));title.setTextSize(16);title.setPadding(16,0,8,0);toolbar.addView(title,new LinearLayout.LayoutParams(0,(int)(48*getResources().getDisplayMetrics().density),1));Button menu=new Button(this);menu.setText("Menu");toolbar.addView(menu);menu.setOnClickListener(v->{PopupMenu popup=new PopupMenu(this,menu);popup.getMenu().add("DM workspace");popup.getMenu().add("Player form");popup.getMenu().add("About offline release");popup.setOnMenuItemClickListener(item->{String name=item.getTitle().toString();if(name.equals("DM workspace"))web.loadUrl(BASE+"DMOS.html");else if(name.equals("Player form"))new AlertDialog.Builder(this).setTitle("Open player form?").setMessage("Download your character before leaving the form. Switching pages discards an unfinished form.").setPositiveButton("Open",(d,w)->web.loadUrl(BASE+"Player-form.html")).setNegativeButton("Cancel",null).show();else new AlertDialog.Builder(this).setTitle("DMOS Table 1.2.0").setMessage("All app files are bundled. Includes SRD references and EF Alpha Races. EF: Quest LLC / quest.rasht. Artwork: Mopodraws. No personal starter party. This app has no Internet permission. Campaigns stay in private app storage; export backups before uninstalling.").setPositiveButton("OK",null).show();return true;});popup.show();});root.addView(toolbar);
 web=new WebView(this);root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setDatabaseEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setGeolocationEnabled(false);settings.setJavaScriptCanOpenWindowsAutomatically(false);settings.setSupportMultipleWindows(false);settings.setCacheMode(WebSettings.LOAD_NO_CACHE);settings.setBlockNetworkLoads(true);web.setBackgroundColor(Color.rgb(16,21,18));web.addJavascriptInterface(new LocalFiles(),"NativeFiles");
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){if(local(request.getUrl()))return false;Toast.makeText(MainActivity.this,"External links are disabled in this offline release.",Toast.LENGTH_SHORT).show();return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri u=request.getUrl();if(!local(u))return denied();String name=u.getPath().substring("/assets/".length());if(name.contains("..")||name.contains("\\"))return denied();try{InputStream stream=getAssets().open(name);String mime=mime(name);Map<String,String> headers=new HashMap<>();headers.put("Content-Security-Policy","default-src 'self'; script-src 'self' 'unsafe-inline' 'wasm-unsafe-eval'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data: blob:; connect-src 'self'; worker-src 'self' blob:; object-src 'none'; base-uri 'self'; form-action 'self'");headers.put("X-Content-Type-Options","nosniff");return new WebResourceResponse(mime,mime.startsWith("text/")||mime.equals("application/json")?"UTF-8":null,200,"OK",headers,stream);}catch(IOException e){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",null,new ByteArrayInputStream(new byte[0]));}}});
 web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(chooser!=null)chooser.onReceiveValue(null);chooser=callback;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("*/*");intent.putExtra(Intent.EXTRA_LOCAL_ONLY,true);intent.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,params.getMode()==FileChooserParams.MODE_OPEN_MULTIPLE);try{startActivityForResult(intent,IMPORT);}catch(ActivityNotFoundException e){chooser.onReceiveValue(null);chooser=null;Toast.makeText(MainActivity.this,"No local file picker is available.",Toast.LENGTH_LONG).show();}return true;}@Override public boolean onConsoleMessage(ConsoleMessage message){if(message.messageLevel()==ConsoleMessage.MessageLevel.ERROR)android.util.Log.e("DMOS",message.message());return true;}});
 if(state!=null)web.restoreState(state);else web.loadUrl(BASE+"DMOS.html");}
 private WebResourceResponse denied(){return new WebResourceResponse("text/plain","UTF-8",403,"Local Only",null,new ByteArrayInputStream(new byte[0]));}
 private String mime(String p){String s=p.toLowerCase(Locale.ROOT);if(s.endsWith(".html"))return "text/html";if(s.endsWith(".js")||s.endsWith(".mjs"))return "text/javascript";if(s.endsWith(".css"))return "text/css";if(s.endsWith(".json"))return "application/json";if(s.endsWith(".pdf"))return "application/pdf";if(s.endsWith(".wasm"))return "application/wasm";if(s.endsWith(".svg"))return "image/svg+xml";if(s.endsWith(".png"))return "image/png";if(s.endsWith(".jpg"))return "image/jpeg";if(s.endsWith(".woff2"))return "font/woff2";return "application/octet-stream";}
 public class LocalFiles {
 @JavascriptInterface public void media(String command){runOnUiThread(()->{android.media.AudioManager audio=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);int code;switch(command){case "previous":code=KeyEvent.KEYCODE_MEDIA_PREVIOUS;break;case "next":code=KeyEvent.KEYCODE_MEDIA_NEXT;break;case "play-pause":code=KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE;break;case "stop":code=KeyEvent.KEYCODE_MEDIA_STOP;break;case "volume-up":audio.adjustStreamVolume(android.media.AudioManager.STREAM_MUSIC,android.media.AudioManager.ADJUST_RAISE,android.media.AudioManager.FLAG_SHOW_UI);return;case "volume-down":audio.adjustStreamVolume(android.media.AudioManager.STREAM_MUSIC,android.media.AudioManager.ADJUST_LOWER,android.media.AudioManager.FLAG_SHOW_UI);return;default:return;}audio.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,code));audio.dispatchMediaKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,code));});}
 @JavascriptInterface public void shareText(String name,String body){if(body==null||body.length()>5000000)return;runOnUiThread(()->{try{File folder=new File(getCacheDir(),"sheets");folder.mkdirs();String filename="DMOS-"+UUID.randomUUID().toString()+"-sheets.html";File file=new File(folder,filename);try(FileOutputStream out=new FileOutputStream(file)){out.write(body.getBytes(StandardCharsets.UTF_8));}Uri uri=Uri.parse("content://"+getPackageName()+".sheets/"+filename);Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/html");send.putExtra(Intent.EXTRA_STREAM,uri);send.setClipData(ClipData.newRawUri("Player sheets",uri));send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(send,"Share player sheets"));}catch(Exception e){Toast.makeText(MainActivity.this,"Could not open sharing: "+e.getMessage(),Toast.LENGTH_LONG).show();}});}
 @JavascriptInterface public void printSheet(String html){if(html==null||html.length()>5000000)return;runOnUiThread(()->{if(printWeb!=null)printWeb.destroy();final WebView sheet=new WebView(MainActivity.this);printWeb=sheet;sheet.getSettings().setJavaScriptEnabled(false);sheet.getSettings().setBlockNetworkLoads(true);sheet.getSettings().setAllowFileAccess(false);sheet.setWebViewClient(new WebViewClient(){@Override public void onPageFinished(WebView view,String url){PrintManager manager=(PrintManager)getSystemService(PRINT_SERVICE);manager.print("DMOS player sheets",sheet.createPrintDocumentAdapter("DMOS player sheets"),null);}});sheet.loadDataWithBaseURL(null,html,"text/html","UTF-8",null);});}
@JavascriptInterface public void saveText(String name,String body,String type){if(body==null||body.length()>100000000)return;runOnUiThread(()->{if(pendingExport!=null){Toast.makeText(MainActivity.this,"Finish the current save first.",Toast.LENGTH_SHORT).show();return;}pendingExport=body.getBytes(StandardCharsets.UTF_8);pendingName=name==null?"DMOS-export.json":name.replaceAll("[\\\\/:*?\"<>|]","_");Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType(type==null?"application/json":type);intent.putExtra(Intent.EXTRA_TITLE,pendingName);intent.putExtra(Intent.EXTRA_LOCAL_ONLY,true);try{startActivityForResult(intent,EXPORT);}catch(ActivityNotFoundException e){pendingExport=null;web.evaluateJavascript("window.DMOS_EXPORT_RESULT&&window.DMOS_EXPORT_RESULT(false)",null);Toast.makeText(MainActivity.this,"No local save picker is available.",Toast.LENGTH_LONG).show();}});}@JavascriptInterface public void printPage(){runOnUiThread(()->{PrintManager manager=(PrintManager)getSystemService(PRINT_SERVICE);manager.print("DMOS Table",web.createPrintDocumentAdapter("DMOS Table"),null);});}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==IMPORT&&chooser!=null){ArrayList<Uri> uris=new ArrayList<>();if(result==RESULT_OK&&data!=null){if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());}chooser.onReceiveValue(uris.isEmpty()?null:uris.toArray(new Uri[0]));chooser=null;}if(request==EXPORT){if(result!=RESULT_OK)web.evaluateJavascript("window.DMOS_EXPORT_RESULT&&window.DMOS_EXPORT_RESULT(false)",null);byte[] bytes=pendingExport;pendingExport=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&bytes!=null){Uri uri=data.getData();new Thread(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("No local output stream");out.write(bytes);runOnUiThread(()->{web.evaluateJavascript("window.DMOS_EXPORT_RESULT&&window.DMOS_EXPORT_RESULT(true)",null);Toast.makeText(this,"Saved local file.",Toast.LENGTH_SHORT).show();});}catch(IOException e){runOnUiThread(()->{web.evaluateJavascript("window.DMOS_EXPORT_RESULT&&window.DMOS_EXPORT_RESULT(false)",null);new AlertDialog.Builder(this).setTitle("Save failed").setMessage(e.getMessage()+". Export again; the campaign remains in the app.").setPositiveButton("OK",null).show();});}}).start();}}}
 @Override protected void onSaveInstanceState(Bundle state){web.saveState(state);super.onSaveInstanceState(state);}@Override public void onConfigurationChanged(Configuration config){super.onConfigurationChanged(config);}@Override public void onBackPressed(){if(web.canGoBack())web.goBack();else new AlertDialog.Builder(this).setTitle("Close DMOS?").setMessage("Saved campaign changes remain on this device. Unfinished form edits are not saved.").setPositiveButton("Close",(d,w)->finish()).setNegativeButton("Stay",null).show();}@Override protected void onDestroy(){if(chooser!=null)chooser.onReceiveValue(null);if(printWeb!=null)printWeb.destroy();web.removeJavascriptInterface("NativeFiles");web.destroy();super.onDestroy();}
}
